#pragma once
#include <ostream>
#include "ir/ssa/ssa_ir.h"
namespace nanopass {
inline void printSSAOperand(const SSAOperand&o,std::ostream&out){if(std::holds_alternative<ValueId>(o))out<<std::get<ValueId>(o).str();else std::visit([&](auto&&v){out<<v;},std::get<CoreConstantVal>(o));}
inline void printSSA(const SSAProgram&p,std::ostream&out){for(const auto&f:p.functions){out<<"func @"<<f.name<<"(";for(size_t i=0;i<f.parameters.size();++i){if(i)out<<", ";out<<f.parameters[i].value.str()<<" : int";}out<<") {\n";for(const auto&b:f.blocks){out<<b.id.str()<<"."<<b.label<<":\n";for(const auto&phi:b.phis){out<<"  "<<phi.result.str()<<" = phi ";for(size_t i=0;i<phi.incoming.size();++i){if(i)out<<", ";out<<"["<<phi.incoming[i].predecessor.str()<<": "<<phi.incoming[i].value.str()<<"]";}out<<" ; "<<phi.originalLocal.str()<<"\n";}for(const auto&i:b.instructions){out<<"  ";if(i.result)out<<i.result->str()<<" = ";if(i.kind==SSAInstructionKind::Constant)std::visit([&](auto&&v){out<<"const "<<v;},i.constantValue);else if(i.kind==SSAInstructionKind::Binary){out<<binaryOpToString(i.binaryOp)<<" ";printSSAOperand(i.operand1,out);out<<", ";printSSAOperand(i.operand2,out);}else if(i.kind==SSAInstructionKind::Unary){out<<unaryOpToString(i.unaryOp)<<" ";printSSAOperand(i.operand1,out);}else if(i.kind==SSAInstructionKind::Call){out<<"call @"<<i.callee<<"(";for(size_t n=0;n<i.callArgs.size();++n){if(n)out<<", ";printSSAOperand(i.callArgs[n],out);}out<<")";}else out<<"memory-op";out<<"\n";}std::visit([&](auto&&t){using T=std::decay_t<decltype(t)>;out<<"  ";if constexpr(std::is_same_v<T,SSATerminator::Jump>)out<<"jump "<<t.target.str();else if constexpr(std::is_same_v<T,SSATerminator::Branch>){out<<"branch ";printSSAOperand(t.condition,out);out<<", "<<t.thenTarget.str()<<", "<<t.elseTarget.str();}else if constexpr(std::is_same_v<T,SSATerminator::Return>){out<<"return";if(t.value){out<<" ";printSSAOperand(*t.value,out);}}else out<<"unreachable";out<<"\n";},b.terminator.value);}out<<"}\n";}}
} // namespace nanopass
